from .money import MAX_CENTS, cents_to_amount, format_amount, parse_cents


def make_invoice(amounts):
    items = list(amounts)  # copy; caller's input is never mutated
    total_cents = 0
    for item in items:
        total_cents += parse_cents(item)
    if total_cents > MAX_CENTS:
        raise ValueError("invoice total exceeds 1000000.00")
    return {"total": format_amount(cents_to_amount(total_cents)), "count": len(items)}
